`timescale 1ns/1ps
// ADDITIVE clock-only partition of original SIDE71b52f3016e76f1ef9ed3ca81333a73a0866b071dd4fa1c9f5727c49701c550b.
// Generated by tools/hbm_static/generate_static_side.py. No original file edits.
// clk[0] RSQRT8521;[1]SQRT3814;[2]SPexp10813;[3]SPpoly10794;
// [4]SPfinish9139;[5]EGATE13902 register sinks before optimization.
// All roots related1:1 phase0. No added input/output register or function edge.
// MLAT3/ALAT3 arithmetic is PHYSICALLY UNQUALIFIED at production833ps.
// MUT1 changes actual result mux function;MUT2 changes actual Engram sign.
module ot_hbm_su_static_side #(parameter integer MUT=0, parameter integer MLAT=3, ALAT=3) (
    input wire [5:0] clk,
    input  wire        rst_n,
    input  wire        v,
    input  wire [2:0]  fn,          // the S code at the S input
    input  wire [31:0] x,
    input  wire [2:0]  fn_out,      // the S code at the S output
    output wire [31:0] y,
    output wire        fault
);
    wire [2:0] output_fn=fn_out ^ (MUT==1 ? 3'd1:3'd0);
    localparam [2:0] SFU_RSQRT = 2, SFU_SQRT = 3, SFU_SPSQRT = 6, SFU_EGATE = 7;
    localparam integer D_EXP = 7 * MLAT + 8 * ALAT + 4;    // ot_hdc_v41x_exp DEPTH: 49 at 3 / 3
    localparam integer KS = (MLAT != 3 || ALAT != 3) ? 1 : 0;
    wire [31:0] y_rsq, y_sq, y_sp, y_eg;
    wire f_rsq, f_sq, f_sp, f_eg1, f_eg2, f_eg3, f_eg4;
    ot_hdc_v41x_rsqrt #(.LM(MLAT), .LA(ALAT)) u_rsq (.clk(clk[0]), .rst_n(rst_n), .v(v && fn == SFU_RSQRT), .x(x), .y(y_rsq), .vo(),
                             .fault(f_rsq));
    ot_hdc_fsqrt u_sq (.clk(clk[1]), .rst_n(rst_n), .v(v && fn == SFU_SQRT), .a(x), .y(y_sq), .vo(), .fault(f_sq));
    ot_hbm_su_static_side_softplus #(.LM(MLAT), .LA(ALAT)) u_sp (.clk(clk[4:2]), .rst_n(rst_n), .v(v && fn == SFU_SPSQRT), .x(x), .sp(), .r(y_sp),
                               .vo(), .fault(f_sp));
    // Engram gate
    reg  [31:0] eg_m;
    reg         eg_v;
    reg  [31:0] eg_sgn;                 // the sign, along the square root (31)
    wire [31:0] absr = {1'b0, x[30:0]};
    wire        eg_le;                                  // absr <= 1e-6 (0x358637BD)
    ot_hdc_kge #(.W(32), .K(KS)) u_egc (.a(32'h358637BD), .b(absr), .ge(eg_le));
    wire        eg_gt = !eg_le;
    always @(posedge clk[5] or negedge rst_n) begin
        if (!rst_n) eg_v <= 1'b0; else eg_v <= v && fn == SFU_EGATE;
    end
    always @(posedge clk[5]) begin
        eg_m <= eg_gt ? absr : 32'h358637BD;                           // max(|x|, 1e-6)
        eg_sgn <= {eg_sgn[30:0], x[31] && (x[30:0] != 31'd0)};
    end
    wire [31:0] eg_r;
    wire        eg_rv;
    ot_hdc_fsqrt u_egs (.clk(clk[5]), .rst_n(rst_n), .v(eg_v), .a(eg_m), .y(eg_r), .vo(eg_rv), .fault(f_eg1));
    reg  [31:0] eg_s;
    reg         eg_sv;
    always @(posedge clk[5] or negedge rst_n) begin
        if (!rst_n) eg_sv <= 1'b0; else eg_sv <= eg_rv;
    end
    always @(posedge clk[5]) eg_s <= {eg_r[31] ^ eg_sgn[31] ^ (MUT==2), eg_r[30:0]};
    // sigmoid(eg_s) = 1 / (exp(-eg_s) + 1)
    wire [31:0] e_y, den;
    wire [D_EXP:0] ve;
    ot_hdc_vline #(.D(D_EXP)) u_ve (.clk(clk[5]), .rst_n(rst_n), .v(eg_sv), .vd(ve));
    ot_hdc_v41x_exp #(.LM(MLAT), .LA(ALAT)) u_exp (.clk(clk[5]), .rst_n(rst_n), .v(eg_sv), .x({~eg_s[31], eg_s[30:0]}), .y(e_y), .vo(),
                           .fault(f_eg2));
    ot_hdc_qadd_lat #(.KEEP(KS), .LAT(ALAT)) u_den (clk[5], rst_n, ve[D_EXP], e_y, 32'h3F800000, den, f_eg3);
    wire [ALAT:0] vd;
    ot_hdc_vline #(.D(ALAT)) u_vd (.clk(clk[5]), .rst_n(rst_n), .v(ve[D_EXP]), .vd(vd));
    ot_hdc_v41x_fdiv u_div (.clk(clk[5]), .rst_n(rst_n), .v(vd[ALAT]), .a(32'h3F800000), .b(den), .y(y_eg), .vo(),
                            .fault(f_eg4));
    assign y = (output_fn == SFU_RSQRT) ? y_rsq : (output_fn == SFU_SQRT) ? y_sq : (output_fn == SFU_SPSQRT) ? y_sp : y_eg;
    assign fault = f_rsq | f_sq | f_sp | f_eg1 | f_eg2 | f_eg3 | f_eg4;
endmodule


module ot_hbm_su_static_side_softplus #(
    parameter integer LM = 3,                   // multiplier latency (ot_hdc_qmul_lat)
    parameter integer LA = 3                    // add latency (ot_hdc_qadd_lat: 3, or 4 input cut)
) (
    input wire [2:0] clk,
    input  wire        rst_n,
    input  wire        v,
    input  wire [31:0] x,
    output wire [31:0] sp,
    output wire [31:0] r,
    output wire        vo,
    output wire        fault
);
    localparam integer T_EXP  = 7 * LM + 8 * LA + 4;   // ot_hdc_v41x_exp DEPTH
    localparam integer T_DEN  = T_EXP + LA;
    localparam integer T_U    = T_DEN + 19;
    localparam integer T_U2   = T_U + LM;
    localparam integer T_P    = T_U2 + 8 * (LM + LA);
    localparam integer T_UP   = T_P + LM;
    localparam integer T_L    = T_UP + LM;
    localparam integer T_SP   = T_L + LA;
    localparam integer DEPTH  = T_SP + 31;       // 162 (LM 3), 180 (LM 4)
    localparam [32*9-1:0] C = {32'h3D70F0F1, 32'h3D888889, 32'h3D9D89D9, 32'h3DBA2E8C, 32'h3DE38E39,
                               32'h3E124925, 32'h3E4CCCCD, 32'h3EAAAAAB, 32'h3F800000};  // 1/17 .. 1/1
    function automatic [31:0] coef(input integer i);
        coef = C[32*(8-i) +: 32];
    endfunction

    wire [DEPTH:0] vd;
    ot_hdc_vline #(.D(DEPTH)) u_v (.clk(clk[0]), .rst_n(rst_n), .v(v), .vd(vd));
    assign vo = vd[DEPTH];

    wire [31:0] t, den, t_d, u, u2, lp, l;
    wire f_exp, f_den, f_div, f_u2, f_up, f_l, f_sp, f_sq;
    ot_hdc_v41x_exp #(.LM(LM), .LA(LA)) u_exp (.clk(clk[0]), .rst_n(rst_n), .v(v), .x({1'b1, x[30:0]}), .y(t), .vo(), .fault(f_exp));
    ot_hdc_qadd_lat #(.KEEP((LM != 3 || LA != 3) ? 1 : 0), .LAT(LA)) a_den (clk[0], rst_n, vd[T_EXP], t, 32'h40000000, den, f_den);
    ot_hdc_delay #(.W(32), .D(LA)) d_t (clk[0], rst_n, t, t_d);
    ot_hdc_v41x_fdiv u_div (.clk(clk[0]), .rst_n(rst_n), .v(vd[T_DEN]), .a(t_d), .b(den), .y(u), .vo(), .fault(f_div));
    ot_hdc_qmul_lat #(LM) m_u2 (clk[0], rst_n, vd[T_U], u, u, u2, f_u2);

    wire [31:0] u2d [0:7];
    wire [31:0] pm  [1:8];
    wire [31:0] pa  [0:8];
    wire [16:1] hf;
    assign u2d[0] = u2;
    assign pa[0] = coef(0);
    genvar k;
    generate
        for (k = 1; k <= 8; k = k + 1) begin : g_h
            if (k < 8) begin : g_d
                ot_hdc_delay #(.W(32), .D(LM + LA)) d_u2 (clk[1], rst_n, u2d[k-1], u2d[k]);
            end
            ot_hdc_qmul_lat #(LM) u_m (clk[1], rst_n, vd[T_U2 + (LM + LA)*(k-1)], pa[k-1], u2d[k-1], pm[k], hf[2*k-1]);
            ot_hdc_qadd_lat #(.KEEP((LM != 3 || LA != 3) ? 1 : 0), .LAT(LA)) u_a (clk[1], rst_n, vd[T_U2 + (LM + LA)*(k-1) + LM], pm[k], coef(k), pa[k], hf[2*k]);
        end
    endgenerate

    wire [31:0] u_d;
    ot_hdc_delay #(.W(32), .D(T_P - T_U)) d_u (clk[1], rst_n, u, u_d);
    ot_hdc_qmul_lat #(LM) m_up (clk[1], rst_n, vd[T_P], u_d, pa[8], lp, f_up);
    ot_hdc_qmul_lat #(LM) m_l  (clk[1], rst_n, vd[T_UP], lp, 32'h40000000, l, f_l);

    reg  [31:0] mx;
    wire [31:0] mx_d, spv;
    wire x_nan = (x[30:23] == 8'hFF) && (x[22:0] != 23'd0);
    always @(posedge clk[2]) mx <= (x[31] && !x_nan) ? 32'd0 : x;
    ot_hdc_delay #(.W(32), .D(T_L - 1)) d_mx (clk[2], rst_n, mx, mx_d);
    ot_hdc_qadd_lat #(.KEEP((LM != 3 || LA != 3) ? 1 : 0), .LAT(LA)) a_sp (clk[2], rst_n, vd[T_L], mx_d, l, spv, f_sp);

    ot_hdc_fsqrt u_sq (.clk(clk[2]), .rst_n(rst_n), .v(vd[T_SP]), .a(spv), .y(r), .vo(), .fault(f_sq));
    ot_hdc_delay #(.W(32), .D(DEPTH - T_SP)) d_sp (clk[2], rst_n, spv, sp);

    wire f_sp_d;
    ot_hdc_delay #(.W(1), .D(DEPTH - T_SP), .RESET(1)) d_fsp (clk[2], rst_n, f_sp, f_sp_d);
    assign fault = f_sp_d | f_sq | f_exp | f_den | f_div | f_u2 | (|hf) | f_up | f_l;
endmodule
